        "group": frame["group"],
        "replaces_table_only_task": True,
        "new_title": frame["new_title"],
    }
    guidance = result.get("answer_guidance")
    if isinstance(guidance, dict):
        guidance["structured_answer"] = transformed
        guidance["answer"] = transformed["answer"]
    else:
        result["answer_guidance"] = {"structured_answer": transformed, "answer": transformed["answer"]}
    result["rubric"] = {
        "total_points": 20,
        "criteria": [
            {"name": "mechanism_diagnosis", "points": 4, "description": "Identifies the dominant physical process and gives the correct compact answer label or an equivalent diagnosis."},
            {"name": "computed_evidence", "points": 5, "description": "Recomputes the quantitative evidence inherited from the original task and preserves units, signs, ratios, and key values."},
            {"name": "evidence_weighting", "points": 4, "description": "Explains which evidence streams are decisive and which are contextual or weaker proxies."},
            {"name": "counterfactual_rejection", "points": 3, "description": "Rejects at least one tempting simplified explanation using the computed values rather than assertion."},
            {"name": "bounded_interpretation", "points": 2, "description": "States scale, timing, proxy, or uncertainty limits without adding unsupported losses or impacts."},
            {"name": "json_contract", "points": 2, "description": "Returns the requested structured mechanism-diagnosis JSON without reducing the answer to a row-only table or same-scale checklist."},
        ],
    }
    if frame.get("formula_prompt"):
        result["rubric"] = {
            "total_points": 20,
            "criteria": [
                {"name": "mechanism_diagnosis", "points": 3, "description": "Identifies the dominant physical process and gives the correct compact mechanism label or equivalent diagnosis."},
                {"name": "computed_evidence", "points": 4, "description": "Recomputes the package-derived quantitative evidence with correct units, signs, ratios, dates, and rounding."},
                {"name": "formula_derivation", "points": 3, "description": "Shows the requested physical formula, scaling relation, or timing relation and connects it to the computed values."},
                {"name": "evidence_weighting", "points": 3, "description": "Explains which evidence streams are decisive and which are contextual or weaker proxies."},
                {"name": "counterfactual_rejection", "points": 3, "description": "Rejects tempting simplified explanations using computed values rather than assertion."},
                {"name": "bounded_interpretation", "points": 2, "description": "States scale, timing, proxy, or uncertainty limits without adding unsupported losses or impacts."},
                {"name": "json_contract", "points": 2, "description": "Returns the requested structured mechanism-diagnosis JSON without reducing the answer to a row-only table."},
            ],
        }

    return result

def find_repo_root(start: Path) -> Path:
    for candidate in [start, *start.parents]:
        package_dir = candidate / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
        if package_dir.is_dir():
            return candidate
    raise FileNotFoundError("Could not locate the CSX-039 event package")


def load_json(path: Path) -> dict:
    return json.loads(path.read_text(encoding="utf-8-sig"))


def wind_chill_c(temperature_c: float, wind_speed_kmh: float) -> float | None:
    if temperature_c > 10.0 or wind_speed_kmh <= 4.8:
        return None
    return (
        13.12
        + 0.6215 * temperature_c
        - 11.37 * wind_speed_kmh**0.16
        + 0.3965 * temperature_c * wind_speed_kmh**0.16
    )


def clean_html_text(raw_html: str) -> str:
    no_tags = re.sub(r"<[^>]+>", " ", raw_html)
    return html.unescape(re.sub(r"\s+", " ", no_tags))


def extract_report_metrics(report_html: str) -> dict[str, object]:
    text = clean_html_text(report_html)
    metrics: dict[str, object] = {}

    ski = re.search(r"7,000 feet recorded nearly ([0-9]+) feet", text)
    middle = re.search(r"5,000\s*-\s*6,000 feet.*?between ([0-9]+)-([0-9]+) feet", text)
    downtown = re.search(r"downtown Los Angeles saw ([0-9]+) inches", text)
    beverley = re.search(r"Beverley Hills saw ([0-9]+) inches of rain", text)

    if ski:
        metrics["snow_7000ft_ft"] = int(ski.group(1))
    if middle:
        metrics["snow_5000_6000ft_ft"] = [int(middle.group(1)), int(middle.group(2))]
    if "Two inches fell in La Crescenta" in text:
        metrics["la_crescenta_snow_in"] = 2
    if downtown:
        metrics["downtown_rain_in"] = int(downtown.group(1))
    if beverley:
        metrics["beverley_hills_rain_in"] = int(beverley.group(1))

    return metrics


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    repo_root = find_repo_root(task_dir)
    package_root = repo_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

    event_meta = load_json(package_root / "metadata" / "event.json")
    anchor = load_json(
        package_root
        / "data"
        / "event_reports"
        / "event_reports_003_Locked_event_anchor_February_2023_Southern_California_winter_storm.json"
    )
    point_weather = load_json(
        package_root
        / "data"
        / "physical_hazard"
        / "physical_hazard_001_Open-Meteo_historical_archive_cold_variables.json"
    )
    report_html = (
        package_root
        / "data"
        / "event_reports"
        / "event_reports_004_01_Locked_package_evidence_report.html.html"
    ).read_text(encoding="utf-8", errors="ignore")

    hourly = point_weather["hourly"]
    times = hourly["time"]
    snowfall = [float(value) for value in hourly["snowfall"]]
    temperatures = [float(value) for value in hourly["temperature_2m"]]
    wind_speeds = [float(value) for value in hourly["wind_speed_10m"]]
    gusts = [float(value) for value in hourly["wind_gusts_10m"]]

    snowfall_total_cm = round(sum(snowfall), 2)
    snowfall_hours = sum(1 for value in snowfall if value > 0)

    longest_snow_run = 0
    run = 0
    for value in snowfall:
        if value > 0:
            run += 1
            longest_snow_run = max(longest_snow_run, run)
        else:
            run = 0

    min_temp_c = min(temperatures)
    below_freezing_hours = sum(1 for value in temperatures if value <= 0)
    freezing_degree_hours_c = round(sum(max(0.0, -value) for value in temperatures), 1)

    wind_chills = [
        (wind_chill_c(temp, wind), index)
        for index, (temp, wind) in enumerate(zip(temperatures, wind_speeds))
    ]
    valid_chills = [(value, index) for value, index in wind_chills if value is not None]
    min_chill_c, min_chill_index = min(valid_chills)
    min_chill_c = round(min_chill_c, 1)

    max_gust_kmh = max(gusts)
    max_gust_index = gusts.index(max_gust_kmh)
    min_temp_index = temperatures.index(min_temp_c)
    report_metrics = extract_report_metrics(report_html)

    basin_metrics = {
        "snow_cm": snowfall_total_cm,
        "snow_h": snowfall_hours,
        "min_t_c": min_temp_c,
        "below0_h": below_freezing_hours,
        "fdh_c_h": freezing_degree_hours_c,
        "wind_chill_c": min_chill_c,
